import sys

def is_L_R_continuous(n, m, roads, L, R):
    dp = [float('inf')] * (n + 1)
    dp[1] = 0
    for _ in range(n - 1):
        for a, b, c in roads:
            if dp[a] != float('inf') and dp[a] + c < dp[b]:
                dp[b] = dp[a] + c
    path_lengths = set()
    queue = [(1, 0)]
    while queue:
        current, dist = queue.pop()
        if current == n:
            path_lengths.add(dist)
            continue
        for a, b, c in roads:
            if a == current and dp[b] == dist + c:
                queue.append((b, dist + c))
    return path_lengths == set(range(L, R + 1))

def generate_roads(n, m):
    from itertools import combinations
    edges = list(combinations(range(1, n + 1), 2))
    for comb in combinations(edges, m):
        yield list(comb)

def main():
    import sys
    L, R = map(int, sys.stdin.read().strip().split())
